<script setup lang="ts">
import { Plus, Pencil, Clock3, RefreshCw } from '@lucide/vue'
import type { ShiftCode } from '../domain/types'
import { saveShift, applyTimeTemplate, cloneWorkspace } from '../domain/commands'
import { clockLabel, shiftHours, shiftStyle, unitLabels } from '../domain/shifts'
const w = useWorkspace(), edit = ref<ShiftCode | null>(null), existing = ref(false), manualDuration = ref(false), template = ref<'A' | 'B' | '8' | null>(null), syncConfirm = ref(false)
function open(s?: ShiftCode) { existing.value = !!s; edit.value = s ? JSON.parse(JSON.stringify(s)) : { code: '', label: '', unit: 'igd', kind: 'regular', start: '07:00', end: '15:00', durationOverride: null, active: true }; manualDuration.value = edit.value!.durationOverride !== null }
async function submit() {
  if (!edit.value) return
  const s = { ...edit.value, code: edit.value.code.trim().toUpperCase(), durationOverride: manualDuration.value ? edit.value.durationOverride : null }
  if (!existing.value && w.data.value?.shifts.some(s2 => s2.code === s.code)) { useNotifications().notify('Kode ini sudah terdaftar. Edit kode yang tersedia.', true); return }
  if (await w.mutate(data => saveShift(data, s, w.role.value), `Menyimpan master dinas ${s.code}`, true)) edit.value = null
}
async function applyTemplate() { if (!template.value) return; const t = template.value; if (await w.mutate(data => applyTimeTemplate(data, t, w.role.value), `Mengubah master ke template ${t}`, true)) template.value = null }
async function sync() {
  const ok = await w.mutate(data => {
    const p = data.plans[w.activeMonth.value]!
    if (p.locked) throw new Error('Buka kunci bulan sebelum memperbarui jam dinas.')
    p.shiftSnapshot = JSON.parse(JSON.stringify(data.shifts))
    return data
  }, `Memperbarui snapshot jam ${w.activeMonth.value}`, true)
  if (ok) syncConfirm.value = false
}
</script>
<template>
  <PageHeading title="Kode & jam dinas" eyebrow="Pemetaan dinas"><button v-if="w.isAdmin.value" class="btn btn-primary" :disabled="w.saving.value" @click="open()"><Plus :size="16"/>Tambah kode</button></PageHeading>
  <div class="mb-6 grid gap-4 lg:grid-cols-3"><button v-for="t in [{ key: 'A', label: 'Pilihan A', times: '08–14 / 14–20 / 20–08', hours: '6 / 6 / 12 jam' }, { key: 'B', label: 'Pilihan B', times: '07–14 / 14–21 / 21–07', hours: '7 / 7 / 10 jam' }, { key: '8', label: 'Tiga shift 8 jam', times: '07–15 / 15–23 / 23–07', hours: '8 / 8 / 8 jam' }]" :key="t.key" class="panel p-5 text-left transition-colors hover:border-brand-200 disabled:cursor-default" :disabled="!w.isAdmin.value || w.saving.value" @click="template = t.key as typeof template"><div class="flex items-center justify-between"><h2 class="text-sm font-semibold">{{ t.label }}</h2><Clock3 :size="17" class="text-brand-600"/></div><p class="mt-3 text-sm text-slate-600">{{ t.times }}</p><p class="mt-2 text-xs font-semibold text-brand-700">{{ t.hours }}</p><p class="mt-3 text-xs text-slate-600">PSI / MI / PSR / MR tetap 12 jam</p></button></div>
  <section class="panel overflow-hidden"><div class="scrollbar-thin overflow-x-auto"><table class="w-full text-left text-xs"><thead class="table-head"><tr><th class="px-5 py-4">Kode</th><th class="px-4 py-4">Arti dinas</th><th class="px-4 py-4">Layanan</th><th class="px-4 py-4">Jam mulai–selesai</th><th class="px-4 py-4 text-right">Durasi</th><th class="px-4 py-4">Status</th><th class="px-4 py-4"><span class="sr-only">Aksi</span></th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="s in w.data.value?.shifts" :key="s.code"><td class="px-5 py-4"><span class="tag font-semibold" :class="shiftStyle(s)">{{ s.code }}</span></td><td class="min-w-40 px-4 py-4 font-medium">{{ s.label }}</td><td class="px-4 py-4 text-slate-600">{{ unitLabels[s.unit] }}</td><td class="whitespace-nowrap px-4 py-4 text-slate-600">{{ clockLabel(s) }}</td><td class="px-4 py-4 text-right font-semibold tabular-nums">{{ shiftHours(s) }} jam</td><td class="px-4 py-4 text-slate-600">{{ s.active ? 'Aktif' : 'Nonaktif' }}</td><td class="px-4 py-4"><button v-if="w.isAdmin.value" :aria-label="`Edit kode ${s.code}`" class="rounded-lg p-2 text-slate-600 hover:bg-brand-50 hover:text-brand-700" @click="open(s)"><Pencil :size="15"/></button></td></tr></tbody></table></div></section>
  <div class="panel mt-6 flex flex-col justify-between gap-4 p-5 sm:flex-row sm:items-center"><div><p class="text-sm font-semibold">Jam bulan terpilih</p></div><button v-if="w.isAdmin.value" class="btn btn-secondary shrink-0" :disabled="!w.plan.value || w.plan.value.locked || w.saving.value" @click="syncConfirm = true"><RefreshCw :size="15"/>Perbarui bulan ini</button></div>
  <AppModal v-if="edit" :title="existing ? `Edit kode ${edit.code}` : 'Tambah kode dinas'" @close="edit = null"><form class="space-y-4" @submit.prevent="submit"><div class="grid grid-cols-2 gap-4"><div><label for="code" class="label">Kode dinas</label><input id="code" v-model="edit.code" class="field uppercase" :disabled="existing" maxlength="16" required/></div><div><label for="unit" class="label">Layanan</label><select id="unit" v-model="edit.unit" class="field"><option v-for="(label, key) in unitLabels" :key="key" :value="key">{{ label }}</option></select></div></div><div><label for="shift-label" class="label">Arti dinas</label><input id="shift-label" v-model="edit.label" class="field" maxlength="140" required/></div><div><label for="kind" class="label">Jenis dinas</label><select id="kind" v-model="edit.kind" class="field"><option value="regular">Reguler</option><option value="long">Dinas panjang</option><option value="custom">Khusus</option><option value="off">Libur</option><option value="leave">Cuti</option><option value="not_started">Belum mulai</option></select></div><div class="grid grid-cols-2 gap-4"><div><label for="start" class="label">Jam mulai</label><input id="start" v-model="edit.start" type="time" class="field"/></div><div><label for="end" class="label">Jam selesai</label><input id="end" v-model="edit.end" type="time" class="field"/></div></div><label class="flex items-center gap-2 text-xs text-slate-600"><input v-model="manualDuration" type="checkbox"/>Durasi khusus</label><div v-if="manualDuration"><label for="override" class="label">Durasi, dalam jam</label><input id="override" v-model.number="edit.durationOverride" type="number" min="0" max="24" step="0.25" class="field" required/></div><label class="flex items-center gap-2 text-xs text-slate-600"><input v-model="edit.active" type="checkbox"/>Kode aktif untuk isian baru</label><div class="flex justify-end gap-2 pt-2"><button type="button" class="btn btn-secondary" @click="edit = null">Batal</button><button class="btn btn-primary" :disabled="w.saving.value">Simpan kode</button></div></form></AppModal>
  <AppModal v-if="template" title="Terapkan pola jam?" @close="template = null"><p class="text-sm leading-relaxed text-slate-600">Jam master akan diganti. Jadwal bulan yang sudah ada tetap menggunakan jam sebelumnya.</p><div class="mt-6 flex justify-end gap-2"><button class="btn btn-secondary" @click="template = null">Batal</button><button class="btn btn-primary" :disabled="w.saving.value" @click="applyTemplate">Terapkan master</button></div></AppModal>
  <AppModal v-if="syncConfirm" title="Perbarui jam bulan ini?" @close="syncConfirm = false"><p class="text-sm leading-relaxed text-slate-600">Rekap dan pemeriksaan bulan {{ w.activeMonth.value }} akan dihitung dengan master terbaru. </p><div class="mt-6 flex justify-end gap-2"><button class="btn btn-secondary" @click="syncConfirm = false">Batal</button><button class="btn btn-primary" :disabled="w.saving.value" @click="sync">Perbarui jam</button></div></AppModal>
</template>
